\label{fd:prop:product}
Let $\mu,\nu$ satisfy \eqref{fd:eq:normalization} and the Frostman conditions with exponents $\alpha,\beta\in(0,2]$. For every rectangular prism as in
Lemma~\ref{fd:lem:localization},
\begin{equation}\label{fd:eq:anisotropic}
 \eta(\mathcal A(W))
 \le C\min\{r_1^\alpha r_2^\beta,
             r_1^\beta r_2^\alpha\}.
\end{equation}
Set $s=\min\{\alpha+\beta,2\}$. For $0<\rho\le\min\{r_1,1\}$,
\begin{equation}\label{fd:eq:prism-bound}
 \eta(\mathcal A(W))\le C\rho^{s-2}r_1r_2.
\end{equation}
Moreover,
\begin{equation}\label{fd:eq:parameter-ball}
 \eta(B_{\mathbb R^4}(z,r))\le Cr^s
\end{equation}
for $z\in\mathbb R^{4},\ 0<r\le1$. All these bounds also hold for any positive
measure $\eta_0\le\eta$.

\label{lem:frostman-annular}
Let $0<t\le2$ and let $\omega$ be a finite positive measure with
compact support in a fixed ball, satisfying
$\omega(B(x,r))\le C_\omega r^t$ for $x\in\mathbb R^2$, $0<r\le1$.
Then

\begin{equation}\label{eq:frostman-annular}
 \int_{R/2\le|\xi|\le2R}|\widehat\omega(\xi)|^2\,d\xi
 \lesssim R^{2-t}\omega(\mathbb R^2)
\end{equation}

for $R\ge1$. Equivalently,

\begin{equation}\label{eq:frostman-annular-polar}
 \int_{R/2}^{2R}rS_\omega(r)\,d r\lesssim R^{2-t}\omega(\mathbb R^2).
\end{equation}

\label{imp:terminal-tail}
For every $\varepsilon_F>0$ and $h\le q\le1$,
\begin{equation}\label{imp:terminal-tail-explicit}
 M(q)\lesssim
 L_w^{(4-t)/(2-t)}w^{-(2\varepsilon_F+t\alpha_c)/(2-t)}(q/w)^{-p_t}.
\end{equation}
The constant may depend on $t,\alpha_c,\beta_c,\varepsilon_F$ and the
original Frostman constant, but not on $R$ or $q$.

\label{imp:fixed-source-bounds}
For every $\varepsilon_{\rm dec}>0$, let
$0<\delta_{\rm freq}\le\delta_0(\varepsilon_{\rm dec})$ be as in
Lemma~\ref{lem:light}. Uniformly for $r\asymp R$,
\begin{equation}\label{imp:light}
 S_\omega^{\mathrm l}(r)\lesssim
 R^{\varepsilon_{\rm dec}}w^{-\beta_c}L_w^4A_{\rm l}(h).
\end{equation}
For $b=1,c$,
\begin{equation}\label{imp:ann}
 \int_{R/2}^{2R}rS_\omega^b(r)\,d r
 \lesssim w^{-\beta_c}L_w^4R^{2-t}.
\end{equation}
For $b=1$, the factor $w^{-\beta_c}L_w^4$ can be omitted.
The constants may depend on the fixed auxiliary parameters and the
original Frostman constant, but not on $R$.

\label{imp:cluster-pair}
Suppose that, at each source point, the symbol $b_1$ is a sum of
sector cutoffs associated with at most $K_\mu$ angular intervals,
whose total length is at most $\Lambda_\mu$. Suppose that $b_2$
has the corresponding bounds $K_\nu,\Lambda_\nu$.
The intervals are unions of the fixed angular cells and may depend
measurably on the source point. Then
\begin{equation}\label{imp:cluster-general}
 \|T_R(b_1,b_2)\|_1
 \lesssim L_w^2\bigl(K_\nu\Lambda_\mu
             +K_\mu\Lambda_\nu+K_\mu K_\nu w\bigr).
\end{equation}
In particular, common bounds $K,\Lambda$ give
$\|T_R(b_1,b_2)\|_1\lesssim(K\Lambda+K^2w)L_w^2$.
For the clustered symbols in \eqref{imp:fixed-symbols},
\begin{equation}\label{imp:cc}
 \|T_R(c,c)\|_{L^1(\,d m(g)\,d z)}
 \lesssim K^2w^{\alpha_c}L_w^2
 \lesssim w^{\alpha_c-2\beta_c}L_w^6.
\end{equation}

\label{imp:layer}
For each layer, at most $CM(q)/(wq)$ transverse bins meet its support,
and every such bin has $\omega_j$-mass at most $Cq$.
The estimates below hold uniformly for $r\asymp R$.
For $b_q=\sum\limits_j\chi_j b_{q,j}$ and every $\varepsilon_F>0$,
\begin{equation}\label{imp:layer-bound}
 S_{\omega}^{b_q}(r)\lesssim
 L_w^{(4-t)/(2-t)}w^{-(2\varepsilon_F+t\alpha_c)/(2-t)}A_{\rm d}(q).
\end{equation}
Hence, the full residual symbol satisfies
\begin{equation}\label{imp:base-residual}
 S_\omega^d(r)\lesssim
 L_w^{(4-t)/(2-t)}w^{-(2\varepsilon_F+t\alpha_c)/(2-t)}A_{\rm d}(h).
\end{equation}
For any positive measures $\tau_j\le b_{q,j}\omega$,
\begin{equation}\label{imp:schur}
 \int_{S^1}\left|\sum_j\chi_j(e)\widehat\tau_j(re)\right|^2\,d\sigma(e)
 \lesssim w\sum_{jk}\tau_j(Q_{jk})^2.
\end{equation}

\label{cor:mixed-exponents}
Let \(1<\alpha,\beta<2\), and suppose that
\begin{equation}\label{eq:mixed-region}
 \alpha^2+\alpha\beta-2\alpha+4\beta-6>0,
 \qquad
 \beta^2+\alpha\beta-2\beta+4\alpha-6>0.
\end{equation}
If \(\mu,\nu\) are compactly supported probability measures with
Frostman exponents \(\alpha,\beta\), respectively, then
\((g_\#\mu)*\widetilde\nu\ll\mathcal L^2\) for almost all \(g\in\mathrm O(2)\).
Hence, for Borel sets \(A,B\) with dimensions \(a,b>1\),
\(\mathcal L^2(gA-B)>0\) for almost all \(g\) if
\begin{equation}\label{eq:mixed-set-region}
 a^2+ab-2a+4b-6>0,
 \qquad b^2+ab-2b+4a-6>0.
\end{equation}
